#!/usr/bin/env python3
"""Final verification of all definition-of-done items."""
import json
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

def connect(host, dtype, user, pwd):
    return ConnectHandler(host=host, device_type=dtype, username=user, password=pwd)

def check_bgp():
    print("=== BGP Sessions (HQ-Edge) ===")
    conn = connect("192.168.122.11", "vyos", "vyos", "test")
    out = conn.send_command("show ip bgp summary", read_timeout=15)
    print(out)
    out = conn.send_command("show ip bgp", read_timeout=15)
    print(out)
    out = conn.send_command("show ip bgp neighbors 203.0.113.1 advertised-routes", read_timeout=15)
    print("ADV to ISP-A:", out)
    out = conn.send_command("show ip bgp neighbors 203.0.113.5 advertised-routes", read_timeout=15)
    print("ADV to ISP-B:", out)
    conn.disconnect()

def check_ospf_neighbors():
    print("\n=== OSPF Adjacencies ===")
    for name, host in [("HQ-Edge","192.168.122.11"),("Hub-A","192.168.122.12"),("Hub-B","192.168.122.13")]:
        conn = connect(host, "vyos", "vyos", "test")
        out = conn.send_command("show ip ospf neighbor", read_timeout=15)
        print(f"{name}: {out}")
        conn.disconnect()
    for name, host in [("Branch-1","192.168.122.21"),("Branch-2","192.168.122.22"),
                       ("Branch-3","192.168.122.23"),("Branch-4","192.168.122.24")]:
        conn = connect(host, "mikrotik_routeros", "admin", "test")
        out = conn.send_command("/routing ospf neighbor print detail", read_timeout=15)
        print(f"{name}: {out}")
        conn.disconnect()

def check_routes():
    print("\n=== Routing Tables ===")
    for name, host in [("HQ-Edge","192.168.122.11"),("Hub-A","192.168.122.12"),("Hub-B","192.168.122.13")]:
        conn = connect(host, "vyos", "vyos", "test")
        out = conn.send_command("show ip route", read_timeout=15)
        print(f"{name}:\n{out}\n")
        conn.disconnect()
    for name, host in [("Branch-1","192.168.122.21"),("Branch-2","192.168.122.22"),
                       ("Branch-3","192.168.122.23"),("Branch-4","192.168.122.24")]:
        conn = connect(host, "mikrotik_routeros", "admin", "test")
        out = conn.send_command("/ip route print detail", read_timeout=15)
        print(f"{name}:\n{out}\n")
        conn.disconnect()

def ping_from_host(host_info, targets):
    name, mgmt, addr = host_info
    results = {}
    try:
        conn = connect(mgmt, "linux", "root", "alpine")
        for tname, tip in targets:
            out = conn.send_command(f"ping -c 2 -W 3 {tip}", read_timeout=15)
            ok = "bytes from" in out.lower() or " 0% packet loss" in out
            results[(name, tname)] = ok
        conn.disconnect()
    except Exception as e:
        for tname, tip in targets:
            results[(name, tname)] = f"ERROR: {e}"
    return results

def main():
    check_bgp()
    check_ospf_neighbors()
    check_routes()

    # Host reachability
    hosts = {
        "B1-PC1": ("192.168.122.31", "10.1.1.10"),
        "B1-PC2": ("192.168.122.32", "10.1.1.11"),
        "B2-PC1": ("192.168.122.33", "10.1.2.10"),
        "B2-PC2": ("192.168.122.34", "10.1.2.11"),
        "B3-PC1": ("192.168.122.35", "10.1.3.10"),
        "B3-PC2": ("192.168.122.36", "10.1.3.11"),
        "B4-PC1": ("192.168.122.37", "10.2.1.10"),
        "B4-PC2": ("192.168.122.38", "10.2.1.11"),
        "B4-PC3": ("192.168.122.39", "10.2.2.10"),
        "B4-PC4": ("192.168.122.40", "10.2.2.11"),
    }

    non_guest = ["B1-PC1","B1-PC2","B2-PC1","B2-PC2","B3-PC1","B3-PC2","B4-PC1","B4-PC2"]
    guest = ["B4-PC3","B4-PC4"]
    internet = [("8.8.8.8", "8.8.8.8"), ("1.1.1.1", "1.1.1.1")]

    print("\n=== Host Reachability ===")
    all_results = {}

    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = []
        for src_name, (src_mgmt, src_addr) in hosts.items():
            targets = []
            # Ping other hosts
            for dst_name, (dst_mgmt, dst_addr) in hosts.items():
                if src_name != dst_name:
                    targets.append((dst_name, dst_addr))
            # Ping internet
            targets.extend(internet)
            futures.append(pool.submit(ping_from_host, (src_name, src_mgmt, src_addr), targets))

        for f in as_completed(futures):
            all_results.update(f.result())

    # Print results
    print("\n--- Non-guest to Non-guest (should all pass) ---")
    ng_pass = 0; ng_fail = 0
    for src in non_guest:
        for dst in non_guest:
            if src != dst:
                r = all_results.get((src, dst), "MISSING")
                if r == True:
                    ng_pass += 1
                else:
                    ng_fail += 1
